def f(g):
    H,W=len(g),len(g[0])
    from collections import Counter
    bg=Counter(x for r in g for x in r).most_common(1)[0][0]
    out=[r[:] for r in g]
    for c in set(x for r in g for x in r)-{bg}:
        for cells in comps(g,c):
            rs=[p for p,q in cells]; cs=[q for p,q in cells]
            h_=max(rs)-min(rs)+1; w_=max(cs)-min(cs)+1
            if (h_,w_)!=(2,2): continue
            rr=set(rs); cc=set(cs)
            miss=None
            for p in rr:
                for q in cc:
                    if (p,q) not in set(cells): miss=(p,q)
            cr=sum(rs)/len(rs); ccv=sum(cs)/len(cs)
            mr,mc=miss
            dr=(1 if cr<mr else -1); dc=(1 if ccv<mc else -1)
            r,c0=mr+dr,mc+dc
            while 0<=r<H and 0<=c0<W and out[r][c0]==bg:
                out[r][c0]=c; r+=dr; c0+=dc
    return out
